use sylva::log::{history::History, Meta, Projection};

#[derive(Default, Clone)]
struct Balance(i64);

impl Projection for Balance {
    type Op = i64;
    type Error = String;
    fn apply(&mut self, op: &i64, _: &Meta) -> Result<(), String> {
        if self.0 + op < 0 {
            return Err("would go below zero".into());
        }
        self.0 += op;
        Ok(())
    }
}

